select department_id AS departmentId, company_id AS companyId, department_name AS departmentName, department_abbreviation AS departmentAbbreviation,
principal_job AS principalJob, principal_name AS principalName, department_startdate AS departmentStartdate, closing_date AS closingDate, department_enddate AS departmentEnddate, comment AS comment, active_flg AS activeFlg from basic_v2_department_management where
department_id = #{departmentId}
